/**
 * @suppress
 */
public object FfiConverterTypeContractListener: FfiConverter<ContractListener, Long> {
    internal val handleMap = UniffiHandleMap<ContractListener>()

    override fun lower(value: ContractListener): Long {
        if (value is ContractListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): ContractListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ContractListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ContractListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ContractListener) = 8UL

    override fun write(value: ContractListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


