 */
public object FfiConverterTypeWebBundle: FfiConverter<WebBundle, Long> {
    override fun lower(value: WebBundle): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): WebBundle {
        return WebBundle(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): WebBundle {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: WebBundle) = 8UL

    override fun write(value: WebBundle, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



