sealed class MobileException: kotlin.Exception() {
    
    class InvalidSettings(
        
        val `reason`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Storage(
        
        val `reason`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NotRunning(
        ) : MobileException() {
        override val message
            get() = ""
    }
    
    class StartFailed(
        
        val `reason`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NoGateways(
        
        val `reason`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Timeout(
        
        val `what`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "what=${ `what` }"
    }
    
    /**
     * `detail` rather than `message`: Kotlin exceptions already have one.
     */
    class Client(
        
        val `kind`: ClientErrorKind, 
        
        val `detail`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "kind=${ `kind` }, detail=${ `detail` }"
    }
    
    class Bundle(
        
        val `reason`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class BackendUnavailable(
        
        val `backend`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "backend=${ `backend` }"
    }
    
    class Internal(
        
        val `reason`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileException = FfiConverterTypeMobileError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeMobileError : FfiConverterRustBuffer<MobileException> {
    override fun read(buf: ByteBuffer): MobileException {
        

        return when(buf.getInt()) {
            1 -> MobileException.InvalidSettings(
                FfiConverterString.read(buf),
                )
            2 -> MobileException.Storage(
                FfiConverterString.read(buf),
                )
            3 -> MobileException.NotRunning()
            4 -> MobileException.StartFailed(
                FfiConverterString.read(buf),
                )
            5 -> MobileException.NoGateways(
                FfiConverterString.read(buf),
                )
            6 -> MobileException.Timeout(
                FfiConverterString.read(buf),
                )
            7 -> MobileException.Client(
                FfiConverterTypeClientErrorKind.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> MobileException.Bundle(
                FfiConverterString.read(buf),
                )
            9 -> MobileException.BackendUnavailable(
                FfiConverterString.read(buf),
                )
            10 -> MobileException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: MobileException): ULong {
        return when(value) {
            is MobileException.InvalidSettings -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is MobileException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is MobileException.NotRunning -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is MobileException.StartFailed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is MobileException.NoGateways -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is MobileException.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`what`)
            )
            is MobileException.Client -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeClientErrorKind.allocationSize(value.`kind`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is MobileException.Bundle -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is MobileException.BackendUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`backend`)
            )
            is MobileException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: MobileException, buf: ByteBuffer) {
        when(value) {
            is MobileException.InvalidSettings -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MobileException.Storage -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MobileException.NotRunning -> {
                buf.putInt(3)
                Unit
            }
            is MobileException.StartFailed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MobileException.NoGateways -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MobileException.Timeout -> {
                buf.putInt(6)
                FfiConverterString.write(value.`what`, buf)
                Unit
            }
            is MobileException.Client -> {
                buf.putInt(7)
                FfiConverterTypeClientErrorKind.write(value.`kind`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is MobileException.Bundle -> {
                buf.putInt(8)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is MobileException.BackendUnavailable -> {
                buf.putInt(9)
                FfiConverterString.write(value.`backend`, buf)
                Unit
            }
            is MobileException.Internal -> {
                buf.putInt(10)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



